  /// zooming out on the way if it's far, and dropping any subject. Input that moves
  /// the map stops it. Draw a frame after.
  void flyTo({
    required double lng,
    required double lat,
    required double zoom,
  }) => RustLib.instance.api.crateApiMapSparkleMapFlyTo(
    that: this,
    lng: lng,
    lat: lat,
    zoom: zoom,
