  String? screenshotPath() =>
      RustLib.instance.api.crateApiMapSparkleMapScreenshotPath(that: this);

  /// A mouse wheel turned by `delta` logical pixels (positive scrolls down).
  void scroll({required double x, required double y, required double delta}) =>
      RustLib.instance.api.crateApiMapSparkleMapScroll(
        that: this,
        x: x,
        y: y,
        delta: delta,
      );

